<?php
namespace Tests\Feature;use App\Models\Admin;use App\Models\Door;use App\Models\Employee;use Illuminate\Foundation\Testing\RefreshDatabase;use Laravel\Sanctum\Sanctum;use Tests\TestCase;
class BuildingAdminEmployee360ScopeTest extends TestCase {use RefreshDatabase;public function test_building_admin_can_read_scoped_employee_but_not_other_building():void{$a=Door::create(['door_id'=>'A','name'=>'A','location'=>'Gedung A']);$b=Door::create(['door_id'=>'B','name'=>'B','location'=>'Gedung B']);$in=Employee::create(['employee_id'=>'IN','nik'=>'N1','name'=>'In','department'=>'Ops']);$out=Employee::create(['employee_id'=>'OUT','nik'=>'N2','name'=>'Out','department'=>'Ops']);$in->doors()->attach($a);$out->doors()->attach($b);$admin=Admin::create(['name'=>'BA','email'=>'ba@test.local','password'=>bcrypt('p'),'role'=>'building_admin','assigned_building'=>'Gedung A']);Sanctum::actingAs($admin);$this->getJson('/api/v1/user-management/employees/'.$in->id.'/360')->assertOk();$this->getJson('/api/v1/user-management/employees/'.$out->id.'/360')->assertForbidden();}}
